/** What `useCustomEvent` hands back. Exported so an app can type a prop or a context
 *  that carries the emitter down a tree instead of calling the hook at every site. */
type SendCustomEvent = (eventName: string, attributes?: JsonMap) => void;
/**
 * Emit a CUSTOM analytics event — the code app's counterpart of the no-code builder's
 * "Send Custom Event" block action (carbon's `useSendCustomEvent`).
 *
 * ```tsx
 * const sendCustomEvent = useCustomEvent();
 * <Button onClick={() => { checkout(); sendCustomEvent('checkout_completed', { plan: 'pro' }); }} />
 * ```
 *
 * Where it lands: the app's **Insights → Events** tab. That dashboard groups rows by
 * `activityType` — i.e. by the string passed as `eventName` — filtered to
 * `activityCategory = 'CUSTOM'` and this app's id. Nothing has to be declared anywhere
 * first: the event list is derived from the collected rows, not from the interface
 * record's `customEvents`, so a name that has never been sent simply has no row yet and
 * a name sent once appears on its own. The flip side is that **the name IS the
 * dimension** — renaming an event splits its history into two rows that nothing joins
 * back together, so pick a name once and keep it.
 *
 * `attributes` rides along on the stored activity row, but the Events module does not
 * chart it today. Put anything you want to see NOW in the event name; use attributes for
 * detail you want recorded against the event for later.
 *
 * Safe to call unconditionally. When `AnalyticsProvider` is not mounted — preview, a
 * public app, an auth route, or `integrations.appAnalytics.enabled` off — there is no
 * analytics context at all and this is a silent no-op (see `InterfaceBoundProvider`,
 * which decides the mount). So an app never needs to branch on whether collection is on,
 * and nothing it emits while off is queued or replayed.
 *
 * Identity is NOT passed here and must not be: the user, the session and the owning app
 * are attributed server-side from the request's session and its `x-ua-app` header (see
 * carbon's `getEventPayload` and uacode's `TrackingRestAPI`). Sending a user id as an
 * attribute duplicates a column the row already has, in a field nobody queries.
 */
declare function useCustomEvent(): SendCustomEvent;

interface AppErrorBoundaryProps {
    children: ReactNode;
    report?: boolean;
    fallback?: ReactNode;
}
interface AppErrorBoundaryState {
    hasError: boolean;
    error: unknown;
}
/**
 * The last line before a white screen.
 *
 * Mounted by AppBuilderProvider, so every generated app gets it without the app's own code
 * mentioning it — which matters because this module is CDN-delivered: an app built months
 * ago picks the boundary up on its next load, and the agent editing that app cannot delete
 * it by editing App.tsx.
 *
 * It catches what React hands a boundary: a throw during render, in a lifecycle, or in a
 * constructor, anywhere below the provider — the failures that leave a blank page.
 *
 * Deliberately NOT a catch-all. A throw in an event handler and a rejected promise never
 * reach React, and the app usually goes on rendering perfectly well after them; treating
 * one as a dead page would put a full-page failure screen over a working app. And nothing
 * in this bundle can see a module graph that never evaluated, because it would be part of
 * that graph — which is what the app template's inline boot guard is for.
 */
declare class AppErrorBoundary extends Component<AppErrorBoundaryProps, AppErrorBoundaryState> {
    state: AppErrorBoundaryState;
    static getDerivedStateFromError(error: unknown): AppErrorBoundaryState;
    componentDidMount(): void;
    componentWillUnmount(): void;
    componentDidCatch(error: unknown, errorInfo: ErrorInfo): void;
    handlePopState: () => void;
    handleReload: () => void;
    render(): ReactNode;
}

