/** What a subscriber receives: the message parsed as JSON, or the raw string when it is
 *  not JSON at all. */
type MqttMessageHandler = (message: unknown) => void;
/** What `useMqttPublish` hands back. Exported so an app can type a prop or a context that
 *  carries the publisher down a tree instead of calling the hook at every site. */
type MqttPublish = (topic: string, payload: unknown) => void;
/**
 * Subscribe to one or more of this app's realtime topics.
 *
 * ```tsx
 * useMqttSubscribe('order-status-updated', () => {
 *   void queryClient.invalidateQueries({ queryKey: ['orders'] });
 * });
 * ```
 *
 * Pass the bare topic name. The app's own id is joined to it under the hood, so two apps
 * that both use `order-status-updated` never hear each other — and a message published by
 * the no-code **Send MQTT event** action or the **Send Mqtt Request** automation node
 * (with this app's id) arrives here.
 *
 * **A message is a hint, not the data.** Nothing is retained and nothing is replayed: a
 * component that mounts a second after a publish receives nothing, and a message sent
 * while the tab was closed is gone. Treat it as "something changed, go re-read", which is
 * why the example refetches rather than writing the payload into state.
 *
 * `onMessage` may be an inline arrow — it is held by reference, so a new one each render
 * does not resubscribe.
 *
 * Safe to call unconditionally. Where the provider is not mounted — preview, a public app,
 * or an auth route — this is a silent no-op, so an app never has to branch on it.
 */
declare function useMqttSubscribe(topic: string | string[] | undefined, onMessage: MqttMessageHandler): void;
/**
 * Publish a message on one of this app's realtime topics.
 *
 * ```tsx
 * const publish = useMqttPublish();
 * publish('order-status-updated', { orderId, status: 'SHIPPED' });
 * ```
 *
 * The payload is serialized as JSON, which is what the no-code listener and the automation
 * node both expect, so a code app and a no-code app can share a topic.
 *
 * Only the copies of the app that are subscribed *right now* receive it. If something must
 * survive a closed tab, write it to a record; this is not a queue.
 *
 * Safe to call unconditionally — a no-op where the provider is not mounted (preview, a
 * public app, an auth route). A publish issued before the connection is ready is queued
 * and flushed on connect rather than dropped.
 */
declare function useMqttPublish(): MqttPublish;

